<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Gateway;

use Override;
use ArrayIterator;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\DcrInitialAccessToken;
use Civi\Lughauth\Shared\Value\Pagination\Slider;

/**
 * @template-extends ArrayIterator<int, DcrInitialAccessToken>
 */
class DcrInitialAccessTokenSlide extends \ArrayIterator
{
    private readonly ?DcrInitialAccessToken $last;
    private readonly DcrInitialAccessTokenCursor $nextCursor;
    public function __construct(
        private readonly ?\Closure $next,
        private readonly ?DcrInitialAccessTokenCursor $cursor,
        private readonly array $values,
        private readonly bool $hasNext = false,
        private readonly int $lookahead = 0
    ) {
        parent::__construct($values);
        $this->last = $values ? end($values) : null;
        $cursor = $this->cursor ?? new DcrInitialAccessTokenCursor(limit: 1000);
        $this->nextCursor = null === $this->last ? $cursor : $cursor->next($this->last, null);
    }
    public function cursor(): ?DcrInitialAccessTokenCursor
    {
        return $this->cursor;
    }
    public function nextCursor(): DcrInitialAccessTokenCursor
    {
        return $this->nextCursor;
    }
    public function hasNext(): bool
    {
        return $this->hasNext;
    }
    public function values(): array
    {
        return $this->values;
    }
    #[Override]
    public function current(): ?DcrInitialAccessToken
    {
        return parent::current();
    }
    public function map(\Closure $fn): DcrInitialAccessTokenSlide
    {
        return new DcrInitialAccessTokenSlide($this->next, $this->cursor, array_map($fn, $this->values), $this->hasNext, $this->lookahead);
    }
    public function slide(\Closure $fn): DcrInitialAccessTokenSlide
    {
        $cursor = $this->cursor;
        $next = $this->next;
        if (null === $cursor || null === $next) {
            return new DcrInitialAccessTokenSlide($next, $cursor, array_values(array_filter($this->values, $fn)));
        }
        $page = Slider::slide(
            $this->values,
            $cursor->limit() + $this->lookahead,
            $cursor->limit(),
            fn (DcrInitialAccessToken $after, int $size): array => $next($this, $cursor->next($after, $size))->values(),
            $fn,
        );
        return new DcrInitialAccessTokenSlide($next, $cursor, $page->items, $page->hasNext);
    }
}
